'use client';

import { IconPlaceholder } from '@/components/icon-placeholder';
import { KbdPlugin, ScriptPlugin, useEditor } from 'platejs/react';
import * as React from 'react';

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/registry/components/editor/dropdown-menu';
import { ToolbarButton } from '@/registry/components/editor/toolbar';

export function MoreToolbarButton() {
  const editor = useEditor();
  const [open, setOpen] = React.useState(false);

  return (
    <DropdownMenu open={open} onOpenChange={setOpen} modal={false}>
      <DropdownMenuTrigger>
        <ToolbarButton pressed={open} tooltip="More formatting">
          <IconPlaceholder lucide="MoreHorizontalIcon" tabler="IconDots" hugeicons="MoreHorizontalCircle01Icon" phosphor="DotsThreeOutlineIcon" remixicon="RiMoreLine" />
        </ToolbarButton>
      </DropdownMenuTrigger>

      <DropdownMenuContent
        className="ignore-click-outside/toolbar flex max-h-[500px] min-w-[180px] flex-col overflow-y-auto"
        align="start"
        onFinalFocus={(event) => {
          event.preventDefault();
          editor.api.dom.focus();
        }}
      >
        <DropdownMenuGroup>
          <DropdownMenuItem
            onSelect={() => {
              editor.update((tx) => {
                tx.plugin(KbdPlugin).toggle();
                tx.selection.collapse({ edge: 'end' });
              });
            }}
          >
            <IconPlaceholder lucide="KeyboardIcon" tabler="IconKeyboard" hugeicons="KeyboardIcon" phosphor="KeyboardIcon" remixicon="RiKeyboardLine" />
            Keyboard input
          </DropdownMenuItem>

          <DropdownMenuItem
            onSelect={() => {
              editor.plugin(ScriptPlugin).update.toggle('sup');
            }}
          >
            <IconPlaceholder lucide="SuperscriptIcon" tabler="IconSuperscript" hugeicons="TextSuperscriptIcon" phosphor="TextSuperscriptIcon" remixicon="RiSuperscript" />
            Superscript
          </DropdownMenuItem>
          <DropdownMenuItem
            onSelect={() => {
              editor.plugin(ScriptPlugin).update.toggle('sub');
            }}
          >
            <IconPlaceholder lucide="SubscriptIcon" tabler="IconSubscript" hugeicons="TextSubscriptIcon" phosphor="TextSubscriptIcon" remixicon="RiSubscript" />
            Subscript
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
